function getRouteInfoFromRoute(route: Route) {
    const [path, query] = route.split('?');
    const name = path;
    const params: Record<string, string> = {};

    if (query) {
        const queryParts = query.split('&');
        for (const part of queryParts) {
            const [key, value] = part.split('=');
            params[key] = value;
        }
    }

    return {name, params};
}

